import{z as l,x as i,o as t,c as m,q as n,j as s,D as r,d as e,s as o,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"模型集成","description":"","frontmatter":{"title":"模型集成","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fml-ensembles.md","filePath":"quant/fml-ensembles.md","lastUpdated":1791063341000}'),d={name:"quant/fml-ensembles.md"};function p(h,a,D,C,f,u){const B=i("Mermaid");return t(),m("div",null,[a[2]||(a[2]=n('<h1 id="模型集成" tabindex="-1">模型集成 <a class="header-anchor" href="#模型集成" aria-label="Permalink to &quot;模型集成&quot;">​</a></h1><div class="epigraph"><p>组合预测的老定理：把误差不太相关的预测平均，方差下降而期望不变；挑权重的那份聪明，常常被权重自身的估计误差吃掉。</p><footer>—— 据 Bates and Granger, Operational Research Quarterly, 1969；Stock and Watson, Journal of Business &amp; Economic Statistics, 2004 整理</footer></div><p><a href="/quant/fml-tscv-deep">上一课</a>给协议配了配得上它的裁判，单个模型由此拿到折外证书。缺口：单模型的折外 IC 本身是抽样噪声——换个随机种子重跑，排名可能翻转。要不要用一台更大的机器把这份噪声摊平，就是本课的问题。集成发生在预测层：多个模型对同一目标给出预测，合成一个信号；权重层面的组合是组合构建课程的对象，不在这里。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>集成的收益来自方差削减，代价从两个方向来。成员相关性：若成员共享特征、样本与超参，误差高度相关，平均之后方差下不去——有效成员数远小于名义成员数。权重过拟合：金融信号弱，日频 IC 常在 \\(0.02\\) 到 \\(0.05\\) 之间，估计一组最优权重所需的样本远大于数据能给的数量；Granger–Ramanathan 式的回归权重在小样本上追噪声，stacking 的二级学习器还要自己过一遍时序清洗，而多数实现没有——把四课以前刚堵上的泄漏，从二级学习器的后门又放了回来。</p><p><span class="marginnote">回归权（Granger–Ramanathan）翻译成大白话：拿各成员的折外预测当自变量、真实值当因变量做一次回归，把回归系数当权重。日频 IC 只有 0.02–0.05 时信号太弱，权重的真实差异常淹没在抽样噪声里——估 20 个权重的误差，可能比不用权重本身还大。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>装配分三层。第一层制造多样性：种子、训练窗、特征子集、算法族、标签视野都可以当差异源；验收多样性的口径是成员间误差相关性，不是成员各自的 IC——两个 IC 都平庸但误差几乎不相关的成员，比两个优异但同源的成员更有用。第二层组合规则从简到繁：等权，按折外精度反比加权，回归权，体制条件混合；默认等权，任何更复杂规则的采用都按<a href="/quant/fml-model-selection-protocol">模型选择协议</a>计入 \\(N\\) 台账。第三层验收：集成后的折外分数在 CPCV 路径分布上与<strong>最强单成员</strong>比，不与平均成员比——基线错了，集成永远在赢。</p>',8)),(t(),s(A,null,{default:r(()=>[o(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DIV%5B%22%E5%A4%9A%E6%A0%B7%E6%80%A7%E6%9D%A5%E6%BA%90%EF%BC%9A%E7%AA%97%E3%80%81%E7%89%B9%E5%BE%81%E3%80%81%E7%AE%97%E6%B3%95%E3%80%81%E6%A0%87%E7%AD%BE%22%5D%20--%3E%20POOL%5B%22%E6%88%90%E5%91%98%E6%B1%A0%22%5D%0A%20%20POOL%20--%3E%20CORR%5B%22%E8%AF%AF%E5%B7%AE%E7%9B%B8%E5%85%B3%E6%80%A7%E9%AA%8C%E6%94%B6%22%5D%0A%20%20CORR%20--%3E%20RULE%5B%22%E7%BB%84%E5%90%88%E8%A7%84%E5%88%99%EF%BC%9A%E7%AD%89%E6%9D%83%E8%B5%B7%E6%AD%A5%22%5D%0A%20%20RULE%20--%3E%20REG%5B%22%E5%9B%9E%E5%BD%92%E6%9D%83%E4%B8%8E%E4%BD%93%E5%88%B6%E6%B7%B7%E5%90%88%EF%BC%9A%E8%AE%A1%E5%85%A5%20N%22%5D%0A%20%20REG%20--%3E%20EVAL%5B%22CPCV%20%E5%AF%B9%E6%AF%94%E6%9C%80%E5%BC%BA%E5%8D%95%E6%88%90%E5%91%98%22%5D%0A%20%20EVAL%20--%3E%7C%22%E8%83%9C%E5%87%BA%22%7C%20DEPLOY%5B%22%E4%B8%8A%E7%BA%BF%EF%BC%9A%E9%9B%86%E6%88%90%E4%BD%9C%E4%B8%BA%E5%8D%95%E4%B8%80%E4%BF%A1%E5%8F%B7%E6%BA%90%22%5D%0A%20%20EVAL%20--%3E%7C%22%E4%B8%8D%E8%83%9C%22%7C%20KEEP%5B%22%E4%BF%9D%E7%95%99%E6%9C%80%E5%BC%BA%E5%8D%95%E6%88%90%E5%91%98%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("方差分解给出预算表：\\(m\\) 个成员误差方差 \\(\\sigma^2\\)、两两相关 \\(\\rho\\)，等权平均的方差是 \\(\\rho\\sigma^2+(1-\\rho)\\sigma^2/m\\)，随 \\(m\\) 增大收敛到下限 \\(\\rho\\sigma^2\\)；\\(\\rho=0.6\\) 时堆再多成员也只降到六成——降低 \\(\\rho\\)（换差异源）比增加 \\(m\\) 有用。等权为什么常胜：权重估计的方差是二阶代价，信号弱时「真权重」本身难辨，"),E("a",{href:"/quant/cov-shrinkage"},"宏观预测里「\\(1/N\\) 几乎不可击败」"),e("的发现在这里更成立；回归权的收益要覆盖它的估计方差才值得上账。体制条件混合的诱惑与代价：若体制判定本身不稳定，混合权重把体制噪声乘进信号，集成变成切换噪声的放大器——先验证体制分类器的稳定性，再谈条件权重。")],-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"把方差公式代入数字：取 \\(\\sigma^2=1\\)、\\(\\rho=0.6\\)，10 个成员的等权方差 \\(=0.6+0.4/10=0.64\\)，堆到 100 个也只到 0.604；而若把 \\(\\rho\\) 压到 0.3，同样 10 个成员就到 \\(0.3+0.7/10=0.37\\)。换差异源的收益远大于堆数量。")],-1)),(t(),s(A,null,{default:r(()=>[o(B,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20Q%5B%22%E7%AD%89%E6%9D%83%E6%96%B9%E5%B7%AE%EF%BC%9Arho*sigma2%20%2B%20(1-rho)*sigma2%2Fm%22%5D%20--%3E%20A%5B%22%E4%BD%8E%20rho%EF%BC%9A%E8%AF%AF%E5%B7%AE%E4%B8%8D%E7%9B%B8%E5%85%B3%22%5D%0A%20%20Q%20--%3E%20B%5B%22%E9%AB%98%20rho%EF%BC%9A%E6%88%90%E5%91%98%E5%90%8C%E6%BA%90%22%5D%0A%20%20A%20--%3E%20A1%5B%22m%20%E7%BF%BB%E5%80%8D%EF%BC%8C%E6%96%B9%E5%B7%AE%E8%BF%91%E4%BC%BC%E5%87%8F%E5%8D%8A%22%5D%0A%20%20A1%20--%3E%20A2%5B%22%E5%A0%86%E6%88%90%E5%91%98%E6%9C%89%E6%95%88%22%5D%0A%20%20B%20--%3E%20B1%5B%22m%20%E5%86%8D%E5%A4%A7%E4%B9%9F%E6%94%B6%E6%95%9B%E5%88%B0%20rho*sigma2%22%5D%0A%20%20B1%20--%3E%20B2%5B%22%E5%85%88%E6%8D%A2%E5%B7%AE%E5%BC%82%E6%BA%90%E9%99%8D%20rho%22%5D%0A%20%20A2%20--%3E%20W%5B%22%E5%B7%AE%E5%BC%82%E6%BA%90%EF%BC%9A%E7%A7%8D%E5%AD%90%E3%80%81%E7%AA%97%E3%80%81%E7%89%B9%E5%BE%81%E5%AD%90%E9%9B%86%E3%80%81%E7%AE%97%E6%B3%95%E6%97%8F%22%5D%0A%20%20B2%20--%3E%20W%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">「跟最强单成员比」的直觉类比：拔河比赛的裁判不能因为你队里平均力气大就判你赢，要看你能不能赢过对面最强的那个壮汉。基线选成平均成员，集成几乎永远在「赢」，但这胜利不带来扣费后的效用。</span></p><p><span class="marginnote">有效成员数 \\(m_{\\mathrm{eff}}=m/(1+(m-1)\\rho)\\)：取 \\(\\rho=0.5\\)、\\(m=20\\) 时 \\(m_{\\mathrm{eff}}\\approx 1.9\\)。二十个同源模型的集成，在方差上约等于两个独立模型；先看这张表，再决定要不要上 stacking。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Bagging 与 boosting 的算法细节不在此展开，树内嵌套是模型自身的事；集成不创造信息——它压预测方差，不提高信息含量，成员共享的泄漏会被集成原样平均保留，<a href="/quant/fml-feature-store-deep">特征存储</a>的契约与<a href="/quant/fml-tscv-deep">切分</a>的清洗对每个成员同样有效。</p><p><span class="marginnote">常见误区：以为 stacking 一定优于等权。二级学习器要重新估一组权重、自己也是一次模型选择，金融信号弱时它的估计方差常把理论收益吃光；若它没重过一遍时序清洗，泄漏还会从后门回流——复杂规则的账要算全。</span>集成也不豁免解释义务：成员变多后「模型在看什么」更难回答，这是下一课的题目。若集成只服务稳定性而不服务扣费后效用，保留最强单成员是合法结论，上一课的弃权在这里同样适用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>集成的预算表是误差相关性：方差下限 \\(\\rho\\sigma^2\\)，降 \\(\\rho\\) 优先于堆 \\(m\\)。</li><li>多样性按成员间误差相关性验收，不按各自 IC 验收。</li><li>组合规则等权起步，复杂规则计入 \\(N\\)；stacking 的二级学习器必须重过全部时序清洗。</li><li>基线是最强单成员，不是平均成员；不胜保留单成员是合法输出。</li><li>出处：Bates and Granger, <em>Operational Research Quarterly</em>, 1969；Granger and Ramanathan, <em>Journal of Forecasting</em>, 1984；Stock and Watson, <em>JBES</em>, 2004。</li></ul>',7))])}const F=l(d,[["render",p]]);export{g as __pageData,F as default};
